1: /** Platform-neutral serial coordination. No command execution, network or persistence.
2:  * Registry and host attestations are trusted inputs, never imported from Task Context.
3:  */
4: import { createHash, randomUUID } from 'node:crypto';
5: import { lstatSync, readFileSync, readdirSync, realpathSync } from 'node:fs';
6: import path from 'node:path';
7: 
8: export const digest = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
9: export const operationBinding = host => digest(host.requests ?? {});
10: export const taskBinding = task => digest({ id: task.id, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions });
11: const copy = value => JSON.parse(JSON.stringify(value));
12: const assert = (ok, message) => { if (!ok) throw new Error(message); };
13: const recovered = new WeakMap();
14: const runtimeTasks = new WeakSet();
15: const runtimeExecutions = new WeakMap();
16: const states = new Set(['pending', 'running', 'completed', 'reused', 'skipped', 'evidence_insufficient', 'permission_blocked', 'validation_failed', 'interrupted']);
17: const allowedCapabilities = ['read_files', 'write_files', 'run_shell_commands', 'access_network', 'destructive_actions_allowed'];
18: const safePath = p => typeof p === 'string' && p !== '' && !path.isAbsolute(p) && !p.split(/[\\/]/).includes('..');
19: 
20: function checkPath(root, relative) {
21:   assert(safePath(relative), 'Dependency path must be repository-relative');
22:   let current = realpathSync(root);
23:   for (const part of relative.split(/[\\/]/)) {
24:     current = path.join(current, part);
25:     try { assert(!lstatSync(current).isSymbolicLink(), 'Symlink paths require host inspection'); }
26:     catch (error) { if (error.code !== 'ENOENT') throw error; }
27:   }
28:   return current;
29: }
30: 
31: // Include directory membership (new/deleted files), executable bits and file bytes.
32: // Never follow symlinks or read outside the explicitly supplied repository root.
33: export function fingerprint(root, relative) {
34:   const current = checkPath(root, relative);
35:   try { lstatSync(current); } catch (error) { if (error.code === 'ENOENT') return 'missing'; throw error; }
36:   function visit(file) {
37:     const stat = lstatSync(file);
38:     assert(!stat.isSymbolicLink(), 'Symlink dependencies require host inspection');
39:     if (stat.isDirectory()) return readdirSync(file).sort().map(name => [name, visit(path.join(file, name))]);
40:     assert(stat.isFile(), 'Only regular files/directories can be fingerprinted');
41:     return [stat.mode & 0o111, createHash('sha256').update(readFileSync(file)).digest('hex')];
42:   }
43:   return digest(visit(current));
44: }
45: 
46: export function captureEvidence(root, input, environment) {
47:   assert(input.id && input.source && input.summary, 'Evidence needs id, source and summary');
48:   assert(Array.isArray(input.dependencies) && input.dependencies.length, 'Evidence needs dependency coverage');
49:   const bindings = Object.fromEntries(input.dependencies.map(p => [p, fingerprint(root, p)]));
50:   return { ...copy(input), bindings, environment: copy(environment), recorded_at: new Date().toISOString() };
51: }
52: 
53: export function evidenceValidity(evidence, host) {
54:   if (!evidence || !host.trustedEvidence?.has(digest(evidence))) return { status: 'unknown', reason: 'source_not_attested' };
55:   if (!['pass', 'fail'].includes(evidence.result)) return { status: 'unknown', reason: 'result_not_observed' };
56:   let unknownReason = evidence.coverage_complete !== true || !evidence.bindings || !Object.keys(evidence.bindings).length
57:     || !evidence.environment || !Object.keys(evidence.environment).length
58:     ? 'dependency_or_environment_coverage_unknown' : null;
59:   if (evidence.kind === 'test' && (!evidence.command || !evidence.cwd || !Number.isInteger(evidence.exit_code) || (evidence.result === 'pass' ? evidence.exit_code !== 0 : evidence.exit_code === 0))) {
60:     unknownReason ??= 'execution_receipt_missing';
61:   }
62:   if (evidence.kind === 'signal' && (!evidence.command || !evidence.cwd || !Number.isInteger(evidence.exit_code)
63:       || evidence.observed_target_failure !== true || !evidence.success_criterion || !evidence.failure_criterion)) {
64:     unknownReason ??= 'reliable_failure_signal_missing';
65:   }
66:   for (const [key, value] of Object.entries(evidence.environment ?? {})) {
67:     if (!(key in (host.environment ?? {}))) { unknownReason ??= `environment_unknown:${key}`; continue; }
68:     if (host.environment[key] !== value) return { status: 'stale', reason: `environment_changed:${key}` };
69:   }
70:   for (const [file, hash] of Object.entries(evidence.bindings ?? {})) {
71:     try {
72:       if (fingerprint(host.root, file) !== hash) return { status: 'stale', reason: `dependency_changed:${file}` };
73:     } catch (error) { unknownReason ??= error.message; }
74:   }
75:   if (unknownReason) return { status: 'unknown', reason: unknownReason };
76:   return evidence.result === 'pass' ? { status: 'valid', reason: 'attested_inputs_unchanged' } : { status: 'failed', reason: 'observed_failure' };
77: }
78: 
79: export function validationPlan(evidence, host) {
80:   return evidence.map(item => ({ id: item.id, ...evidenceValidity(item, host) }))
81:     .map(item => ({ ...item, action: item.status === 'valid' ? 'reuse' : item.status === 'unknown' ? 'investigate' : 'rerun' }));
82: }
83: 
84: export function reviewBinding(root, task, baseline, files) {
85:   assert(baseline && Array.isArray(files) && files.length, 'Review needs a baseline and complete changed/related paths');
86:   return digest({ baseline, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions,
87:     files: [...new Set(files)].sort().map(file => [file, fingerprint(root, file)]) });
88: }
89: 
90: function definition(task, registry, inventory) {
91:   assert(runtimeTasks.has(task), 'Untrusted Task Context: use createTask or restoreTask');
92:   assert(task.registry_binding === digest(registry), 'Registry changed; explicitly migrate/reselect workflow');
93:   if (task.workflow_id) {
94:     const workflow = registry.workflows[task.workflow_id];
95:     assert(workflow, 'Unknown registered workflow');
96:     return workflow;
97:   }
98:   assert(inventory.has(task.skill_id), 'Unknown single Skill');
99:   return { stages: [{ id: 'task', type: 'skill', skill: task.skill_id, optional: false, condition: 'always', prerequisites: [], next: [], permission: 'request_scoped', stop_conditions: [] }], stop_conditions: [] };
100: }
101: 
102: export function createTask({ id, goal, acceptance, workflow_id = null, skill_id = null }, registry, inventory) {
103:   assert(id && goal && Array.isArray(acceptance) && acceptance.length, 'Goal and acceptance are required');
104:   assert(acceptance.every(item => typeof item === 'string' && item.length) && new Set(acceptance).size === acceptance.length, 'Acceptance IDs must be distinct strings');
105:   assert(Boolean(workflow_id) !== Boolean(skill_id), 'Choose one registered workflow or one existing Skill');
106:   const task = { schema_version: 2, id, goal, acceptance: copy(acceptance), workflow_id, skill_id,
107:     registry_binding: digest(registry), decisions: [], scope: { files: [], modules: [], interfaces: [] },
108:     risks: [], permission_refs: [], evidence: [], changes: [], unresolved: [], next_actions: [],
109:     current_stage: null, steps: {}, history: [] };
110:   runtimeTasks.add(task);
111:   for (const stage of definition(task, registry, inventory).stages) task.steps[stage.id] = { status: 'pending', attempts: 0, evidence_ids: [] };
112:   return task;
113: }
114: 
115: function evidenceFor(task, ids, host) {
116:   return ids?.length > 0 && ids.every(id => {
117:     const evidence = task.evidence.find(e => e.id === id);
118:     return evidence?.task_binding === taskBinding(task) && evidenceValidity(evidence, host).status === 'valid';
119:   });
120: }
121: function condition(task, name, host) {
122:   if (name === 'always') return true;
123:   const fact = host.conditions?.[name];
124:   return fact && typeof fact.value === 'boolean' && fact.reason && evidenceFor(task, fact.evidence_ids, host) ? fact.value : undefined;
125: }
126: function permission(skill, stage, task, host) {
127:   const metadata = host.inventory.get(skill);
128:   if (!metadata || !['draft', 'beta', 'stable'].includes(metadata.status)) return 'skill_unavailable';
129:   const request = host.requests?.[stage.id];
130:   if (!request) return 'operation_scope_missing';
131:   if (!Array.isArray(request.capabilities) || !request.capabilities.length) return 'capabilities_missing';
132:   if (stage.permission === 'write_scoped' && !request.capabilities.includes('write_files')) return 'write_scope_missing';
133:   if (stage.permission === 'read_only' && request.capabilities.includes('write_files')) return 'read_only_stage';
134:   for (const capability of request.capabilities) {
135:     if (!allowedCapabilities.includes(capability) || metadata.permissions?.[capability] !== true
136:         || host.capabilities?.[capability] !== true) return `capability_denied:${capability}`;
137:     const grants = host.grants?.filter(g => g.task_id === task.id && g.capability === capability && g.source
138:       && g.skills.includes(skill)) ?? [];
139:     if (!grants.length) return `user_authorization_missing:${capability}`;
140:     if (['read_files', 'write_files'].includes(capability)) {
141:       if (!request.paths?.length || request.paths.some(p => !safePath(p))) return 'explicit_paths_missing';
142:       if (request.paths.some(p => !grants.some(g => g.paths?.includes(p)))) return `path_not_authorized:${capability}`;
143:       try { for (const p of request.paths) checkPath(host.root, p); } catch { return 'unsafe_path'; }
144:     } else if (!request.operation || !grants.some(g => g.operations?.includes(request.operation))) return `operation_not_authorized:${capability}`;
145:   }
146:   const check = host.skillChecks?.[stage.id];
147:   if (!check?.source || check.request_binding !== digest(request) || check.skill_binding !== digest(metadata) || check.allowed !== true) return 'skill_scope_not_verified';
148:   if (request.capabilities.includes('run_shell_commands') && request.preflight !== 'safe') return 'command_preflight_missing';
149:   return null;
150: }
151: 
152: function potentiallyEffectful(stage, host) {
153:   return host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files') || stage.permission === 'write_scoped';
154: }
155: 
156: function writes(stage, host) {
157:   return stage.permission === 'write_scoped' || (stage.permission === 'request_scoped' && host.requests?.[stage.id]?.capabilities?.includes('write_files'));
158: }
159: 
160: export function reconciliationBinding(task, stageId, host) {
161:   return digest({ intent: taskBinding(task), stage: stageId, step: task.steps[stageId], request: host.requests?.[stageId] });
162: }
163: 
164: export function recoveryBinding(task, host) {
165:   const checkpoint = recovered.get(task);
166:   return checkpoint ? digest({ checkpoint, intent: taskBinding(task), requests: host.requests, skillChecks: host.skillChecks }) : null;
167: }
168: 
169: export function recoveredExecutionBinding(task, stageId, host) {
170:   return digest({ recovery: recoveryBinding(task, host), stage: stageId, attempts: task.steps[stageId]?.attempts, execution_nonce: task.steps[stageId]?.execution_nonce, request: host.requests?.[stageId] });
171: }
172: 
173: function requirement(task, requirement, host) {
174:   return task.evidence.some(e => e.claims?.includes(requirement.claim)
175:     && e.task_binding === taskBinding(task) && e.operation_binding === operationBinding(host)
176:     && (!requirement.skill || e.skill === requirement.skill)
177:     && (!requirement.kind || e.kind === requirement.kind)
178:     && (requirement.kind !== 'review' || (e.kind === 'review' && e.independent === true && host.reviewBinding && e.review_basis === host.reviewBinding))
179:     && evidenceValidity(e, host).status === 'valid');
180: }
181: 
182: function stepEvidence(task, stage, host, executionOwner = task) {
183:   const step = task.steps[stage.id];
184:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
185:   const explicitReuse = step.status === 'reused'
186:     && Array.isArray(host.reuse?.[stage.id]) && digest(host.reuse[stage.id]) === digest(step.evidence_ids);
187:   if (step.status === 'reused' && !explicitReuse) return false;
188:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
189:   const scoped = evidence.filter(e => e.skill === stage.skill && e.request_binding === digest(host.requests[stage.id]) && e.claims?.includes(`stage:${stage.id}`)
190:     && (explicitReuse || (runtimeExecutions.get(executionOwner)?.get(stage.id) === step.execution_nonce
191:       && typeof step.execution_nonce === 'string' && e.execution_attempt === step.attempts
192:       && e.execution_nonce === step.execution_nonce)));
193:   if (!scoped.length) return false;
194:   if (stage.skill === 'safe-code-review' && !scoped.some(e => e.kind === 'review' && e.independent === true
195:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
196:   if (stage.skill === 'bug-root-cause-analysis' && !scoped.some(e => e.signal_ids?.length
197:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal' && signal.task_binding === taskBinding(task)
198:         && evidenceValidity(signal, host).status === 'valid')))) return false;
199:   return true;
200: }
201: 
202: function unresolvedFailures(task, host) {
203:   const unresolved = [];
204:   for (const failed of task.evidence.filter(e => e.kind === 'test' && e.result === 'fail')) {
205:     const validity = evidenceValidity(failed, host);
206:     if (validity.status === 'stale' || validity.reason === 'source_not_attested') continue;
207:     if (validity.status === 'unknown') {
208:       unresolved.push(failed);
209:       continue;
210:     }
211:     const resolution = host.failureResolutions?.get(digest(failed));
212:     const replacement = resolution?.source && task.evidence.find(e => e.id === resolution.replacement);
213:     const identity = e => digest({ command: e.command, cwd: e.cwd, bindings: e.bindings, environment: e.environment });
214:     if (!replacement || replacement.task_binding !== taskBinding(task) || replacement.kind !== 'test'
215:         || evidenceValidity(replacement, host).status !== 'valid' || identity(replacement) !== identity(failed)
216:         || !(Date.parse(replacement.recorded_at) > Date.parse(failed.recorded_at))) {
217:       unresolved.push(failed);
218:     }
219:   }
220:   return unresolved;
221: }
222: 
223: /** Recompute a decision every time. No imported context field grants execution authority. */
224: export function nextAction(task, host) {
225:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
226:   const workflow = definition(task, host.registry, host.inventory);
227:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
228:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
229:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
230:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
231:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
232:   const recovery = recoveryBinding(task, host);
233:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
234:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
235:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
236:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
237:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
238:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
239:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
240:   const completed = new Set();
241:   for (const stage of workflow.stages) {
242:     const step = task.steps[stage.id];
243:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
244:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
245:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
246:     }
247:     const applies = condition(task, stage.condition, host);
248:     const decision = { stage: stage.id, skill: stage.skill };
249:     const stopAssessments = [...new Set([...(workflow.stop_conditions ?? []), ...stage.stop_conditions])].map(name => [name, condition(task, name, host)]);
250:     const stop = stopAssessments.find(([, value]) => value === true);
251:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop[0]}` };
252:     const unknownStop = stopAssessments.find(([, value]) => value === undefined);
253:     if (unknownStop) return { ...decision, action: 'evidence_insufficient', reason: `stop_condition_unknown:${unknownStop[0]}` };
254:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
255:     // Completed effects stay protected even when applicability changes. A new receipt
256:     // is not a reconciliation of the previous attempt's potentially different effects.
257:     const wasCompleted = ['completed', 'reused'].includes(step.status);
258:     const effectful = step.effect_state === 'known' || writes(stage, host)
259:       || host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files');
260:     if (stage.type === 'skill' && wasCompleted) {
261:       const denied = permission(stage.skill, stage, task, host);
262:       if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
263:       if (!stepEvidence(task, stage, host)) {
264:         if (effectful && !evidenceFor(task, step.evidence_ids, host)) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
265:         const reusable = host.reuse?.[stage.id];
266:         if (reusable) {
267:           const provisional = copy(task);
268:           provisional.steps[stage.id].status = 'reused';
269:           provisional.steps[stage.id].evidence_ids = reusable;
270:           if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: reusable, reason: 'explicit_recovered_or_historical_result_reuse' };
271:         }
272:         if (effectful) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
273:       }
274:     }
275:     if (!applies) {
276:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
277:       // Applicability must not erase a completed operation or its known effects.
278:       if (['completed', 'reused'].includes(step.status)) {
279:         if (stage.type === 'skill' && !stepEvidence(task, stage, host)) return { ...decision, action: 'evidence_insufficient', reason: 'historical_stage_requires_explicit_reuse' };
280:         completed.add(stage.id); continue;
281:       }
282:       if (recovery && stage.type === 'skill') {
283:         const reusable = host.reuse?.[stage.id];
284:         if (reusable) {
285:           const provisional = copy(task);
286:           provisional.steps[stage.id].status = 'reused';
287:           provisional.steps[stage.id].evidence_ids = reusable;
288:           const denied = permission(stage.skill, stage, task, host);
289:           if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
290:           if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: reusable, reason: 'observed_effect_before_checkpoint_recovery' };
291:         }
292:         const disposition = host.recoveredExecutionChecks?.get(recoveredExecutionBinding(task, stage.id, host));
293:         if (!disposition?.source || disposition.disposition !== 'not_executed') {
294:           return { ...decision, action: 'blocked', reason: 'recovered_skipped_effect_needs_disposition' };
295:         }
296:       }
297:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
298:       completed.add(stage.id); continue;
299:     }
300:     if (stage.type === 'gate') {
301:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
302:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
303:       for (const child of children) {
304:         const denied = permission(child.skill, child, task, host);
305:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
306:       }
307:       // Always re-evaluate gates against host grants, never reuse persisted approval.
308:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
309:       completed.add(stage.id); continue;
310:     }
311:     const denied = permission(stage.skill, stage, task, host);
312:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
313:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
314:       completed.add(stage.id); continue;
315:     }
316:     const failure = step.status === 'validation_failed';
317:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
318:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
319:     if (potentiallyEffectful(stage, host)) {
320:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
321:         .find(r => !requirement(task, r, host));
322:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
323:     }
324:     const candidate = host.reuse?.[stage.id];
325:     if (candidate) {
326:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate; provisional.steps[stage.id].status = 'reused';
327:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
328:     }
329:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
330:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
331:     }
332:     if (host.verificationDeferral?.active === true) {
333:       const request = host.requests[stage.id];
334:       if (!host.verificationDeferral.source) {
335:         return { ...decision, action: 'evidence_insufficient', reason: 'verification_deferral_source_missing' };
336:       }
337:       if (request.capabilities.includes('run_shell_commands') && typeof request.verification !== 'boolean') {
338:         return { ...decision, action: 'evidence_insufficient', reason: 'command_verification_purpose_unknown' };
339:       }
340:       if (request.verification === true) {
341:         return { ...decision, action: 'evidence_insufficient', reason: 'verification_deferred',
342:           verification_status: 'verification_deferred', source: host.verificationDeferral.source,
343:           pending: host.verificationDeferral.pending ?? [], release_authorized: false };
344:       }
345:     }
346:     if (recovery && stage.type === 'skill') {
347:       const disposition = host.recoveredExecutionChecks?.get(recoveredExecutionBinding(task, stage.id, host));
348:       if (!disposition?.source || !['not_executed', 'safe_retry'].includes(disposition.disposition)
349:           || (disposition.disposition === 'safe_retry' && !host.reconciled?.has(reconciliationBinding(task, stage.id, host)))) {
350:         return { ...decision, action: 'blocked', reason: 'recovered_execution_needs_explicit_disposition' };
351:       }
352:     }
353:     const unresolved = unresolvedFailures(task, host).find(failed => {
354:       const repair = host.failureRepairs?.get(digest(failed));
355:       return !repair?.source || repair.stages?.[stage.id] !== digest(host.requests[stage.id]);
356:     });
357:     if (unresolved) return { ...decision, action: evidenceValidity(unresolved, host).status === 'unknown' ? 'evidence_insufficient' : 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: unresolved.id };
358:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
359:   }
360:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
361:   const obligations = [
